164	jboolean NativeSensorService::sendRuntimeSensorEvent(JNIEnv* env, jint handle, jint type,
165	                                                     jlong timestamp, jfloatArray values) {
166	    if (mService == nullptr) {
167	        ALOGD("Dropping sendRuntimeSensorEvent, sensor service not available.");
168	        return false;
169	    }
170	    if (values == nullptr) {
171	        ALOGD("Dropping sendRuntimeSensorEvent, no values.");
172	        return false;
173	    }
174	
175	    sensors_event_t event{
176	            .version = sizeof(sensors_event_t),
177	            .sensor = handle,
178	            .type = type,
179	            .timestamp = timestamp,
180	    };
181	
182	    int valuesLength = env->GetArrayLength(values);
183	    jfloat* sensorValues = env->GetFloatArrayElements(values, nullptr);
184	
185	    switch (type) {
186	        case SENSOR_TYPE_ACCELEROMETER:
187	        case SENSOR_TYPE_MAGNETIC_FIELD:
188	        case SENSOR_TYPE_ORIENTATION:
189	        case SENSOR_TYPE_GYROSCOPE:
190	        case SENSOR_TYPE_GRAVITY:
191	        case SENSOR_TYPE_LINEAR_ACCELERATION: {
192	            if (valuesLength != 3) {
193	                ALOGD("Dropping sendRuntimeSensorEvent, wrong number of values.");
194	                return false;
195	            }
196	            event.acceleration.x = sensorValues[0];
197	            event.acceleration.y = sensorValues[1];
198	            event.acceleration.z = sensorValues[2];
199	            break;
200	        }
201	        case SENSOR_TYPE_DEVICE_ORIENTATION:
202	        case SENSOR_TYPE_LIGHT:
203	        case SENSOR_TYPE_PRESSURE:
204	        case SENSOR_TYPE_TEMPERATURE:
205	        case SENSOR_TYPE_PROXIMITY:
206	        case SENSOR_TYPE_RELATIVE_HUMIDITY:
207	        case SENSOR_TYPE_AMBIENT_TEMPERATURE:
208	        case SENSOR_TYPE_SIGNIFICANT_MOTION:
209	        case SENSOR_TYPE_STEP_DETECTOR:
210	        case SENSOR_TYPE_TILT_DETECTOR:
211	        case SENSOR_TYPE_WAKE_GESTURE:
212	        case SENSOR_TYPE_GLANCE_GESTURE:
213	        case SENSOR_TYPE_PICK_UP_GESTURE:
214	        case SENSOR_TYPE_WRIST_TILT_GESTURE:
215	        case SENSOR_TYPE_STATIONARY_DETECT:
216	        case SENSOR_TYPE_MOTION_DETECT:
217	        case SENSOR_TYPE_HEART_BEAT:
218	        case SENSOR_TYPE_LOW_LATENCY_OFFBODY_DETECT: {
219	            if (valuesLength != 1) {
220	                ALOGD("Dropping sendRuntimeSensorEvent, wrong number of values.");
221	                return false;
222	            }
223	            event.data[0] = sensorValues[0];
224	            break;
225	        }
226	        default: {
227	            if (valuesLength > 16) {
228	                ALOGD("Dropping sendRuntimeSensorEvent, number of values exceeds the maximum.");
229	                return false;
230	            }
231	            memcpy(event.data, sensorValues, valuesLength * sizeof(float));
232	        }
233	    }
234	
235	    status_t err = mService->sendRuntimeSensorEvent(event);
236	    return err == OK;
237	}
