240	                                                              jint serial, jlong timestamp,
241	                                                              jfloatArray values) {
242	    if (mService == nullptr) {
243	        ALOGD("Dropping sendRuntimeSensorAdditionalInfo, sensor service not available.");
244	        return false;
245	    }
246	
247	    sensors_event_t event{
248	            .version = sizeof(sensors_event_t),
249	            .sensor = handle,
250	            .type = SENSOR_TYPE_ADDITIONAL_INFO,
251	            .timestamp = timestamp,
252	            .additional_info =
253	                    (additional_info_event_t){
254	                            .type = type,
255	                            .serial = serial,
256	                    },
257	    };
258	
259	    if (values != nullptr) {
